import{B as e,Q as t,s as n,z as r}from"./chunks/framework.hue4hZNP.js";import"./chunks/booker-story-arc-card.BnDrnfHh.js";var i=JSON.parse(`{"title":"Build Story Arcs","description":"","frontmatter":{},"headers":[],"relativePath":"guide/build-story-arcs.md","filePath":"guide/build-story-arcs.md"}`),a={name:`guide/build-story-arcs.md`};function o(n,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[e(`<h1 id="build-story-arcs" tabindex="-1">Build Story Arcs <a class="header-anchor" href="#build-story-arcs" aria-label="Permalink to &quot;Build Story Arcs&quot;">​</a></h1><p>A booker&#39;s guide to story arcs — scripted, multi-show feuds with a planned beginning, middle, and blowoff. Where <a href="./manage-rivalries.html">rivalries</a> track <em>heat</em>, story arcs are the <em>script</em>: beats you plan in advance and book onto shows in order.</p><hr><h2 id="step-1-—-launch-the-arc-wizard" tabindex="-1">Step 1 — Launch the arc wizard <a class="header-anchor" href="#step-1-—-launch-the-arc-wizard" aria-label="Permalink to &quot;Step 1 — Launch the arc wizard&quot;">​</a></h2><p>Story arcs hang off a rivalry. From an active rivalry&#39;s detail page, click <strong>Story Arc</strong> — the wizard opens pre-seeded with the two wrestlers.</p><p><img src="/screenshots/booker-story-arc-wizard.png" alt="Story arc wizard"></p><h3 id="wizard-settings" tabindex="-1">Wizard settings <a class="header-anchor" href="#wizard-settings" aria-label="Permalink to &quot;Wizard settings&quot;">​</a></h3><ul><li><strong>Wrestlers</strong> — two for a classic rivalry, <strong>3+ for a multi-wrestler feud</strong> (a stable implosion, a three-way dance for affection).</li><li><strong>Arc Name</strong> — what the card reads on show pages.</li><li><strong>Length</strong> — <strong>Short</strong> (1 PLE), <strong>Medium</strong> (2), or <strong>Long</strong> (3). Length sets how many premium shows the arc spans; beats pace between them.</li></ul><hr><h2 id="step-2-—-plan-the-beats" tabindex="-1">Step 2 — Plan the beats <a class="header-anchor" href="#step-2-—-plan-the-beats" aria-label="Permalink to &quot;Step 2 — Plan the beats&quot;">​</a></h2><p>A <strong>beat</strong> is one chapter of the story — a promo confrontation, an attack, a tag match that goes wrong, a betrayal. The arc&#39;s beats become your booking backlog: each one lands on a show before the next PLE in the arc&#39;s timeline.</p><p>On the arc&#39;s detail page:</p><ul><li><strong>Add Beat</strong> — describe what happens and who&#39;s involved; each beat lists its participants and their role in the story.</li><li><strong>Edit beats</strong> — reorder and rewrite as the story evolves; nothing is locked until booked.</li><li><strong>Beat status</strong> — beats move from planned to booked as you attach them to show segments.</li></ul><p><img src="/screenshots/booker-story-arc-beats.png" alt="Story arc beats"></p><p><img src="/screenshots/booker-story-arc-add-beat.png" alt="Add a beat"></p><hr><h2 id="step-3-—-book-the-beats-onto-shows" tabindex="-1">Step 3 — Book the beats onto shows <a class="header-anchor" href="#step-3-—-book-the-beats-onto-shows" aria-label="Permalink to &quot;Step 3 — Book the beats onto shows&quot;">​</a></h2><p>Each booked beat becomes a segment on the appropriate show — a promo beat becomes a promo segment, a confrontation becomes a match. The show planning views surface which beats still need a home so the story never stalls between PLEs.</p><p>If the AI narration is configured, booked segments inside an active arc get narration that&#39;s aware of the script — commentary references the story so far instead of treating each match as an isolated event.</p><hr><h2 id="step-4-—-land-the-payoff" tabindex="-1">Step 4 — Land the payoff <a class="header-anchor" href="#step-4-—-land-the-payoff" aria-label="Permalink to &quot;Step 4 — Land the payoff&quot;">​</a></h2><p>The arc ends at its final PLE, where the story resolves:</p><ul><li><strong>Winner control</strong> — when creating the arc you choose who decides the ending: <strong>the booker picks</strong> the winner (you&#39;re telling a specific story) or <strong>the AI picks</strong> (the rolls and momentum decide, and you book to whatever happened).</li><li>After the payoff, the arc flips to <strong>completed</strong> and its full beat history stays readable from the arc list.</li></ul><p>Saved arcs render as cards on the Story Arcs page — active arcs first, completed history below.</p><p><img src="/screenshots/booker-story-arc-card.png" alt="Story arc card"></p><hr><h2 id="rivalry-or-story-arc" tabindex="-1">Rivalry or story arc? <a class="header-anchor" href="#rivalry-or-story-arc" aria-label="Permalink to &quot;Rivalry or story arc?&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th>Rivalry (heat)</th><th>Story Arc (scripted)</th></tr></thead><tbody><tr><td>Driven by</td><td>Match outcomes and promos</td><td>Your beat plan</td></tr><tr><td>Ends by</td><td>Resolution rolls, heat decay</td><td>The final PLE payoff</td></tr><tr><td>Best for</td><td>Organic feuds that write themselves</td><td>Stories that need to hit specific moments</td></tr></tbody></table><p>They compose: a hot rivalry is the natural seed for an arc, and booking arc beats keeps the underlying rivalry&#39;s heat climbing.</p><hr><h2 id="where-to-go-next" tabindex="-1">Where to go next <a class="header-anchor" href="#where-to-go-next" aria-label="Permalink to &quot;Where to go next&quot;">​</a></h2><ul><li><a href="./manage-rivalries.html">Manage Rivalries</a> — the heat system underneath.</li><li><a href="./schedule-a-show.html">Schedule a Show</a> — where beats become segments.</li><li>The auto-generated <a href="./booker.html">Booker Overview</a> documents every story-arc screen.</li></ul>`,32)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};